css:
@font-face {
	font-family: "THSarabun";
	src: url("{{ frappe.utils.get_url() }}/assets/erpnext_thailand/fonts/THSarabun.ttf")
		format("truetype");
}

@page {
	margin: 0;
}
/* ปลดล็อค height และ overflow ออกเพื่อให้ขึ้นหน้า 2 ได้ */
html,
body {
	margin: 0;
	padding: 0;
}

.print-format {
	padding: 0 !important;
	margin: 0 !important;
	min-height: unset !important;
	max-width: unset !important;
}

.print-format-preview {
	padding: 0 !important;
}

/* ── Base ── */
.page {
	position: relative;
	width: 210mm;
	height: 280mm;
	background-image: url("/assets/connect_diagnostics_core/images/print_formats/cd_purchase_orders.jpg?v=20260603-jpgpdf1");
	background-size: 100% 100%;
	background-repeat: no-repeat;
	font-family: "Sarabun", Arial, sans-serif;
	color: #575858;
	overflow: hidden; /* คำสั่งนี้อยู่ที่กรอบแต่ละหน้าแทน เพื่อไม่ให้ของล้นออกนอกแผ่น */
}
.f {
	position: absolute;
	line-height: 1.2;
}
.tr {
	text-align: right;
}
.tc {
	text-align: center;
}

.copy-label {
	top: 42mm;
	left: 132mm;
	width: 47mm;
	font-size: 12pt;
}

/* ── Supplier Info ── */
.supplier-code {
	top: 53mm;
	left: 30mm;
	width: 91mm;
	font-size: 8.5pt;
}
.party-name {
	top: 60mm;
	left: 18mm;
	width: 91mm;
	font-size: 8.5pt;
}
.party-address {
	top: 64mm;
	left: 18mm;
	width: 91mm;
	font-size: 8.5pt;
}
.party-mobile {
	top: 81mm;
	left: 28mm;
	font-size: 10pt;
}
.reference {
	top: 88mm;
	left: 28mm;
	font-size: 10pt;
}

/* ── PO Details ── */
.doc-no {
	top: 53mm;
	left: 132mm;
	font-size: 8.5pt;
}
.doc-date {
	top: 58.5mm;
	left: 132mm;
	font-size: 8.5pt;
}
.due-date {
	top: 70.5mm;
	left: 132mm;
	font-size: 8.5pt;
}
.terms {
	top: 75mm;
	left: 132mm;
	font-size: 8.5pt;
}
.incoterm {
	top: 88mm;
	left: 132mm;
	width: 70mm;
	font-size: 10pt;
}

/* ── Items (Columns) ── */
.col-no {
	left: 14mm;
	width: 11mm;
	font-size: 9pt;
}
.col-desc {
	left: 26mm;
	width: 76mm;
	font-size: 8.5pt;
	overflow: hidden;
	white-space: nowrap;
}
.col-wh {
	left: 102mm;
	width: 9mm;
	font-size: 8pt;
}
.col-qty {
	left: 120mm;
	width: 20mm;
	font-size: 9pt;
}
.col-rate {
	left: 141mm;
	width: 21mm;
	font-size: 9pt;
}
.col-disc {
	left: 161mm;
