html:
{%- set co = frappe.db.get_value("Company", doc.company, ["company_name", "company_logo", "tax_id", "phone_no", "website"], as_dict=True) %}
{%- set print_pages = ['ต้นฉบับ/Original', 'สำเนา/Copy'] %}

{% for page_title in print_pages %}
<div class="page">

  {# ── ข้อความบอกสถานะหน้า (ปรับ top, left ได้ตามตำแหน่งที่ต้องการวาง) ── #}
  <div class="f tc copy-label">{{ page_title }}</div>

  {# ── Supplier Info ── #}
  <div class="f supplier-code">{{ doc.supplier}}</div>
  <div class="f party-name">{{ doc.supplier_name }}</div>
  {%- if doc.address_display %}
  <div class="f party-address">{{ doc.address_display }}</div>
  {%- endif %}
  <div class="f party-mobile">{{ doc.contact_mobile or "" }}</div>
  <div class="f reference">{{ doc.order_confirmation_no or "" }}</div>

  {# ── PO Details (right panel) ── #}
  <div class="f doc-no">{{ doc.name }}</div>
  <div class="f doc-date">
    {%- if doc.transaction_date %}
      {%- set d = (doc.transaction_date|string).split(' ')[0].split('-') -%}
      {{ d[2] }}/{{ d[1] }}/{{ ((d[0]|int)|string)[-4:] }}
    {%- endif %}
  </div>

  <div class="f due-date">
    {%- if doc.schedule_date %}
      {%- set sd = (doc.schedule_date|string).split(' ')[0].split('-') -%}
      {{ sd[2] }}/{{ sd[1] }}/{{ ((sd[0]|int)|string)[-4:] }}
    {%- endif %}
  </div>
  <div class="f terms">{{ doc.payment_terms_template or "" }}</div>
  <div class="f incoterm">{{ doc.incoterm or "" }}{%- if doc.named_place %} {{ doc.named_place }}{%- endif %}</div>

  {# ── Items ── #}
  {%- for item in doc.items %}
  {%- set rt = 101.0 + loop.index0 * 8.0 %}
  <div class="f tc col-no" style="top:{{ '%.1f'|format(rt) }}mm;">{{ loop.index }}</div>
  <div class="f col-desc" style="top:{{ '%.1f'|format(rt) }}mm;">
    <span>{{ item.item_code }}: </span>{%- if item.item_name and item.item_name != item.item_code %} {{ item.item_name }}{%- endif %}
  </div>
  <div class="f tc col-wh" style="top:{{ '%.1f'|format(rt) }}mm;">{{ (item.warehouse or "").split(" - ")[0] }}</div>
  <div class="f tr col-qty" style="top:{{ '%.1f'|format(rt) }}mm;">{{ "%g"|format(item.qty) }} {{ item.uom }}</div>
  <div class="f tr col-rate" style="top:{{ '%.1f'|format(rt) }}mm;">{{ frappe.utils.fmt_money(item.rate, currency=doc.currency) }}</div>
  <div class="f tr col-disc" style="top:{{ '%.1f'|format(rt) }}mm;">{{ ("%g"|format(item.discount_percentage)) + "%" if item.discount_percentage else "" }}</div>
  <div class="f tr col-amount" style="top:{{ '%.1f'|format(rt) }}mm;">{{ frappe.utils.fmt_money(item.amount, currency=doc.currency) }}</div>
  {%- endfor %}

  {# ── Remark ── #}
  <div class="f remarks">{{ doc.terms or "" }}</div>

  {# ── Totals ── #}
  <div class="f tr total">{{ frappe.utils.fmt_money(doc.total, currency=doc.currency) }}</div>
  <div class="f tr discount">{{ frappe.utils.fmt_money(doc.discount_amount or 0, currency=doc.currency) }}</div>
  <div class="f tr net">{{ frappe.utils.fmt_money(doc.net_total, currency=doc.currency) }}</div>
  <div class="f tr vat">{{ frappe.utils.fmt_money(doc.total_taxes_and_charges or 0, currency=doc.currency) }}</div>
  <div class="f tr bold grand">{{ frappe.utils.fmt_money(doc.rounded_total or doc.grand_total, currency=doc.currency) }}</div>

  {# ── In Words ── #}
  <div class="f amount-words">({{ number_to_thai_currency(doc.grand_total, doc.currency) }}).</div>

</div>

{# ── สั่งให้ขึ้นหน้าใหม่หากยังไม่จบหน้าสุดท้าย ── #}
{% if not loop.last %}
<div style="page-break-after: always;"></div>
{% endif %}

{% endfor %}
